from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Any


def _decimal(value: Any) -> Decimal:
    if value is None:
        return Decimal(0)
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return Decimal(0)


def _id_value(value: Any) -> tuple[int, Any]:
    if value is None:
        return (0, Decimal(0))
    try:
        return (1, Decimal(str(value).strip()))
    except (InvalidOperation, ValueError, TypeError):
        return (2, str(value))


def _same_id(left: Any, right: Any) -> bool:
    return _id_value(left) == _id_value(right)


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indexes.sort(key=lambda index: _id_value(accounts[index].get("ACCT_ID")))

    for index in eligible_indexes:
        account = accounts[index]
        acct_id = account.get("ACCT_ID")

        exposure = Decimal(0)
        for order in orders:
            if (
                _same_id(order.get("ACCT_ID"), acct_id)
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _decimal(order.get("TOT_AMT"))

        credit_limit = _decimal(account.get("CRED_LIMIT"))
        updated = new_accounts[index]
        held = account.get("CRED_HOLD")

        if exposure > credit_limit and held != "Y":
            updated["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * Decimal(8) / Decimal(10) and updated.get("CRED_HOLD", held) == "Y":
            updated["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
